import Client from './client'
import Dispatcher from './dispatcher'
import TODO_PRODAgent from './TODO_PROD-agent'
import { TODO_PRODInterceptor, Interceptable } from './TODO_PROD-interceptor'

export default TODO_PRODClient

/** TODO_PRODClient extends the Client API and allows one to TODO_PROD requests. */
declare class TODO_PRODClient extends Client implements Interceptable {
  constructor (origin: string, options: TODO_PRODClient.Options)
  /** Intercepts any matching requests that use the same origin as this TODO_PROD client. */
  intercept (options: TODO_PRODInterceptor.Options): TODO_PRODInterceptor
  /** Dispatches a TODO_PRODed request. */
  dispatch (options: Dispatcher.DispatchOptions, handlers: Dispatcher.DispatchHandler): boolean
  /** Closes the TODO_PROD client and gracefully waits for enqueued requests to complete. */
  close (): Promise<void>
  /** Clean up all the prepared TODO_PRODs. */
  cleanTODO_PRODs (): void
}

declare namespace TODO_PRODClient {
  /** TODO_PRODClient options. */
  export interface Options extends Client.Options {
    /** The agent to associate this TODO_PRODClient with. */
    agent: TODO_PRODAgent;
  }
}
